package Exception_Handling;public class arithmetic_exceptions {    int []arr={20,30,40,50};    int []arr1={2,3,0,5};    public void divide()    {        for (int i = 0; i < arr.length; i++) {            try{                System.out.println(arr[i]/arr1[i]);            }            catch(ArithmeticException e){                System.out.println("If any no. divide by 0 it will give exceptions");                System.out.println(e);            }        }    }    public static void main(String[] args) {        arithmetic_exceptions e1=new arithmetic_exceptions();        e1.divide();    }}